-- Release A2 production migration contract
CREATE TABLE IF NOT EXISTS mfa_factors(user_id TEXT PRIMARY KEY, secret_encrypted TEXT NOT NULL, status TEXT NOT NULL, recovery_codes_hashes JSONB NOT NULL DEFAULT '[]', recovery_codes_remaining INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS secure_imports(import_id TEXT PRIMARY KEY,user_id TEXT NOT NULL,tenant_id TEXT NOT NULL,workspace_id TEXT NOT NULL,object_key TEXT NOT NULL,file_name TEXT NOT NULL,mime_type TEXT NOT NULL,size BIGINT NOT NULL,sha256 TEXT NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS delivery_attempts(delivery_id TEXT PRIMARY KEY,user_id TEXT NOT NULL,tenant_id TEXT NOT NULL,workspace_id TEXT NOT NULL,channel TEXT NOT NULL,destination TEXT,title TEXT NOT NULL,body TEXT NOT NULL,source_job_id TEXT,status TEXT NOT NULL,provider TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
